		w.String("ci_two_edge_sep")
		if err := v.BaseCIChannel.EncodeOrc(w); err != nil {
			return err
		}
		if err := v.CustomScale.EncodeOrc(w); err != nil {
			return err
		}
		w.Float64(float64(v.MinVal))
		w.Float64(float64(v.MaxVal))
